Rules.InvariantScript:
With(
    {
        nextEvent: First(
            Sort(
                Filter(
                    colECCSCutoverSchedule,
                    StartDate >= Today()
                ),
                StartDate,
                SortOrder.Ascending
            )
        )
    },
    If(
        IsBlank(nextEvent.StartDate),
        "No milestone scheduled",
        nextEvent.EventName &
        " | " &
        Text(
            nextEvent.StartDate,
            "[$-en-US]mmmm d, yyyy"
        )
    )
)

With(
    {
        nextEvent: First(
            Sort(
                Filter(
                    colECCSCutoverSchedule,
                    StartDate >= Now()
                ),
                StartDate,
                SortOrder.Ascending
            )
        )
    },
    If(
        IsBlank(nextEvent.StartDate),
        "COUNTDOWN NOT CONFIGURED",
        With(
            {
                totalMinutes: DateDiff(
                    Now(),
                    nextEvent.StartDate,
                    TimeUnit.Minutes
                )
            },
            If(
                totalMinutes <= 0,
                "EVENT ACTIVE",
                Int(totalMinutes / 1440) &
                "d " &
                Mod(
                    Int(totalMinutes / 60),
                    24
                ) &
                "h " &
                Mod(
                    totalMinutes,
                    60
                ) &
                "m"
            )
        )
    )
)

Table(
    {
        EventName: "",
        Phase: "",
        StartDate: Date(2026, 1, 1),
        FinishDate: Date(2026, 1, 1)
    }
)
